// Shared helpers for ENG-2490 CDP scenarios.
export const cmd = async ({ client, json, vault }, id) =>
  client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:${id}`)});`);

export const openNote = async ({ client, json }, path, { selectFrom, selectTo } = {}) =>
  client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(path)}), { state: { mode: "source" } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    const ed = leaf.view.editor; ed.focus();
    ${selectFrom ? `ed.setSelection(${json(selectFrom)}, ${json(selectTo)});` : ""}
    return true;
  })();`);

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Real mouse input at CSS-pixel coordinates.
export const mouse = async ({ client }, type, x, y, extra = {}) =>
  client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", buttons: type === "mouseReleased" ? 0 : 1, clickCount: 1, ...extra });

export const move = async ({ client }, x, y, pressed = true) =>
  client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y, button: pressed ? "left" : "none", buttons: pressed ? 1 : 0 });

export const click = async (ctx, x, y) => {
  await move(ctx, x, y, false);
  await mouse(ctx, "mousePressed", x, y);
  await mouse(ctx, "mouseReleased", x, y);
};

export const dblclick = async (ctx, x, y) => {
  await click(ctx, x, y);
  await mouse(ctx, "mousePressed", x, y, { clickCount: 2 });
  await mouse(ctx, "mouseReleased", x, y, { clickCount: 2 });
};

export const key = (code, key, vk, extra = {}) => ({ key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk, ...extra });
// Canvas helpers for ENG-2490 CDP scenarios.
import fs from "node:fs";
import { cmd, sleep } from "./lib.mjs";

const STATE = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/dad56eb0-85c8-43af-afe3-79e3dc24c31b/scratchpad/cdp/canvas-state.json";
export const NT = { evidence: "node_zPr4p680Cvs8QItPn4ZyP", claim: "node_cPwy7vUeOLdF2fv49i-DC" };
export const fm = (id, body = "body") => `---\nnodeTypeId: ${id}\n---\n${body}\n`;

export const readState = () => (fs.existsSync(STATE) ? JSON.parse(fs.readFileSync(STATE, "utf8")) : {});
export const writeState = (s) => fs.writeFileSync(STATE, JSON.stringify(s, null, 2));

// Expose the tldraw editor of the active canvas leaf as window.__dgEditor.
export const grabEditor = ({ client }) =>
  client.waitFor(`
    const root = app.workspace.activeLeaf?.view?.containerEl;
    const c = root?.querySelector(".tl-canvas");
    if (!c) return false;
    const k = Object.keys(c).find((x) => x.startsWith("__reactFiber$"));
    let f = c[k];
    while (f && !f.memoizedProps?.value?.putExternalContent) f = f.return;
    if (!f) return false;
    window.__dgEditor = f.memoizedProps.value;
    return true;`, { label: "tldraw editor" });

export const collapse = ({ client }) =>
  client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);

// Create a fresh canvas (first call) or reopen the saved one, collapse sidebars, grab the editor.
export const openCanvas = async (ctx, { fresh = false } = {}) => {
  const { client, json } = ctx;
  const st = readState();
  if (fresh || !st.canvas) {
    await cmd(ctx, "create-discourse-graph-canvas");
    await client.waitFor(`return !!app.workspace.activeLeaf?.view?.containerEl.querySelector(".tl-canvas")`, { label: "canvas view" });
    st.canvas = await client.evaluate(`return app.workspace.activeLeaf.view.file.path;`);
    st.viewType = await client.evaluate(`return app.workspace.activeLeaf.view.getViewType();`);
    writeState(st);
  } else {
    await client.evaluate(`return (async () => {
      const leaf = app.workspace.getLeaf("tab");
      await leaf.setViewState({ type: ${json(st.viewType)}, state: { file: ${json(st.canvas)} }, active: true });
      app.workspace.setActiveLeaf(leaf, { focus: true }); return true; })();`);
    await client.waitFor(`return !!app.workspace.activeLeaf?.view?.containerEl.querySelector(".tl-canvas")`, { label: "canvas view" });
  }
  await collapse(ctx);
  await sleep(600);
  await grabEditor(ctx);
  return st;
};

export const shapes = ({ client }) =>
  client.evaluate(`const ed = window.__dgEditor; return ed.getCurrentPageShapes().map((s) => ({ id: s.id, type: s.type, x: s.x, y: s.y, index: s.index, parentId: s.parentId, props: s.props }));`);

// Page point -> viewport (CSS px) point for real mouse input.
export const toScreen = ({ client, json }, p) =>
  client.evaluate(`const ed = window.__dgEditor; const s = ed.pageToScreen(${json(p)}); return { x: s.x, y: s.y };`);

export const centerOf = ({ client, json }, id) =>
  client.evaluate(`const ed = window.__dgEditor; const b = ed.getShapePageBounds(${json(id)}); const s = ed.pageToScreen({ x: b.midX, y: b.midY }); return { x: s.x, y: s.y };`);

export const dropNode = async ({ client, json }, path, point) =>
  client.evaluate(`return (async () => {
    const ed = window.__dgEditor;
    const url = "obsidian://open?vault=" + encodeURIComponent(app.vault.getName()) + "&file=" + encodeURIComponent(${json(path)});
    await ed.putExternalContent({ type: "url", url, point: ${json(point)} });
    return true; })();`);

export const consoleTrap = ({ client }) =>
  client.evaluate(`window.__dgErr = []; if (!window.__dgOrigErr) window.__dgOrigErr = console.error;
    console.error = (...a) => { window.__dgErr.push(a.map(String).join(" ").slice(0, 200)); window.__dgOrigErr(...a); };
    window.__dgOnErr = (e) => window.__dgErr.push("uncaught: " + (e.message || e.reason)); window.addEventListener("error", window.__dgOnErr); window.addEventListener("unhandledrejection", window.__dgOnErr); return true;`);
export const consoleRelease = ({ client }) =>
  client.evaluate(`if (window.__dgOrigErr) console.error = window.__dgOrigErr; window.removeEventListener("error", window.__dgOnErr); window.removeEventListener("unhandledrejection", window.__dgOnErr); return window.__dgErr || [];`);

export { sleep };
// Screencast recorder: own CDP socket on the vault's page, frames -> mp4 with a caption.
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { listTargets } from "/Users/trang.doan/.claude/skills/dg-obsidian-cdp-verify/scripts/driver.mjs";

const OUT = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/dad56eb0-85c8-43af-afe3-79e3dc24c31b/scratchpad/videos";
const FONT = "/System/Library/Fonts/Supplemental/Arial.ttf";

const openSocket = (url) =>
  new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    let id = 0;
    const pending = new Map();
    const handlers = [];
    ws.addEventListener("open", () =>
      resolve({
        send: (method, params = {}) =>
          new Promise((res, rej) => {
            const n = ++id;
            pending.set(n, { res, rej });
            ws.send(JSON.stringify({ id: n, method, params }));
          }),
        on: (fn) => handlers.push(fn),
        close: () => ws.close(),
      }),
    );
    ws.addEventListener("error", reject);
    ws.addEventListener("message", (e) => {
      const msg = JSON.parse(e.data.toString());
      if (msg.id && pending.has(msg.id)) {
        const p = pending.get(msg.id);
        pending.delete(msg.id);
        msg.error ? p.rej(new Error(JSON.stringify(msg.error))) : p.res(msg.result);
      } else if (msg.method) handlers.forEach((h) => h(msg));
    });
  });

const findPage = async (root, port) => {
  for (const t of await listTargets(port)) {
    const s = await openSocket(t.webSocketDebuggerUrl);
    const r = await s.send("Runtime.evaluate", {
      expression: `!!document.querySelector(".workspace") && app?.vault?.adapter?.basePath === ${JSON.stringify(root)}`,
      returnByValue: true,
    });
    if (r.result?.value === true) return s;
    s.close();
  }
  throw new Error("recorder: vault page not found");
};

// Visible cursor: CDP input moves no OS pointer, so draw one that follows DOM pointer events.
const CURSOR_ON = `(() => {
  if (document.getElementById("rec-cursor")) return;
  const c = document.createElement("div");
  c.id = "rec-cursor";
  c.style.cssText = "position:fixed;left:0;top:0;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;background:rgba(255,80,80,.55);border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.4);pointer-events:none;z-index:2147483647;transition:transform .08s";
  document.body.appendChild(c);
  const mv = (e) => { c.style.left = e.clientX + "px"; c.style.top = e.clientY + "px"; };
  const dn = () => { c.style.transform = "scale(.6)"; c.style.background = "rgba(255,40,40,.9)"; };
  const up = () => { c.style.transform = ""; c.style.background = "rgba(255,80,80,.55)"; };
  window.__recCursor = { mv, dn, up };
  window.addEventListener("pointermove", mv, true);
  window.addEventListener("pointerdown", dn, true);
  window.addEventListener("pointerup", up, true);
})()`;
const CURSOR_OFF = `(() => {
  const h = window.__recCursor;
  if (h) { window.removeEventListener("pointermove", h.mv, true); window.removeEventListener("pointerdown", h.dn, true); window.removeEventListener("pointerup", h.up, true); }
  document.getElementById("rec-cursor")?.remove();
})()`;

export const startRecording = async ({ root, port = 9222, slug, caption }) => {
  const dir = path.join(OUT, "frames", slug);
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  const s = await findPage(root, port);
  await s.send("Runtime.evaluate", { expression: CURSOR_ON });
  const frames = [];
  s.on((msg) => {
    if (msg.method !== "Page.screencastFrame") return;
    const { data, metadata, sessionId } = msg.params;
    const file = path.join(dir, `f${String(frames.length).padStart(5, "0")}.jpg`);
    writeFileSync(file, Buffer.from(data, "base64"));
    frames.push({ file, t: metadata.timestamp });
    s.send("Page.screencastFrameAck", { sessionId }).catch(() => {});
  });
  await s.send("Page.startScreencast", { format: "jpeg", quality: 85, maxWidth: 1600, maxHeight: 1100 });
  const t0 = Date.now();
  return {
    stop: async ({ holdMs = 1500 } = {}) => {
      await new Promise((r) => setTimeout(r, holdMs));
      await s.send("Page.stopScreencast").catch(() => {});
      await s.send("Runtime.evaluate", { expression: CURSOR_OFF }).catch(() => {});
      s.close();
      if (frames.length === 0) throw new Error(`recorder: no frames for ${slug}`);
      const list = frames
        .map((f, i) => {
          const next = frames[i + 1]?.t ?? f.t + holdMs / 1000;
          return `file '${f.file}'\nduration ${Math.max(next - f.t, 0.001).toFixed(3)}`;
        })
        .join("\n") + `\nfile '${frames.at(-1).file}'\n`;
      const listFile = path.join(dir, "list.txt");
      writeFileSync(listFile, list);
      const capFile = path.join(dir, "caption.txt");
      writeFileSync(capFile, caption);
      const out = path.join(OUT, `${slug}.mp4`);
      execFileSync("ffmpeg", [
        "-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", listFile,
        "-vf",
        `fps=30,scale=trunc(iw/2)*2:trunc(ih/2)*2,drawtext=fontfile=${FONT}:textfile=${capFile}:x=16:y=h-th-16:fontsize=22:fontcolor=white:box=1:boxcolor=black@0.65:boxborderw=10`,
        "-c:v", "libx264", "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-an", out,
      ]);
      return { out, frames: frames.length, ms: Date.now() - t0 };
    },
  };
};

const wait = (ms) => new Promise((r) => setTimeout(r, ms));

// Pace input for viewers: split long moves into steps, pause on press/release and after direct evaluates.
const paced = (client) => {
  const send = client.send;
  const evaluate = client.evaluate;
  let last = null;
  client.send = async (method, params = {}) => {
    if (method !== "Input.dispatchMouseEvent") return send(method, params);
    if (params.type === "mouseMoved" && last) {
      const steps = Math.min(30, Math.floor(Math.hypot(params.x - last.x, params.y - last.y) / 25));
      for (let k = 1; k < steps; k++) {
        await send(method, { ...params, x: last.x + ((params.x - last.x) * k) / steps, y: last.y + ((params.y - last.y) * k) / steps });
        await wait(16);
      }
    }
    const r = await send(method, params);
    last = { x: params.x, y: params.y };
    await wait(params.type === "mouseMoved" ? 16 : 350);
    return r;
  };
  client.evaluate = async (expr) => {
    const r = await evaluate(expr);
    await wait(250);
    return r;
  };
  return () => {
    client.send = send;
    client.evaluate = evaluate;
  };
};

// Wrap scenarios so each run() is recorded at viewing pace.
export const recorded = (scenarios, { prefix, captionOf = (s) => s.name } = {}) =>
  scenarios.map((sc, i) => ({
    ...sc,
    run: async (ctx, state) => {
      const slug = `${prefix}-${String(i + 1).padStart(2, "0")}-${sc.name.split(" ")[0].replace(/[^\w.-]/g, "")}`;
      const rec = await startRecording({ root: ctx.vault.root, slug, caption: captionOf(sc) });
      const restore = paced(ctx.client);
      try {
        return await sc.run(ctx, state);
      } finally {
        restore();
        const r = await rec.stop();
        console.log(`REC ${r.out} frames=${r.frames} ms=${r.ms}`);
      }
    },
  }));
// T2: ModifyNodeModal search popover position + title textarea auto-height.
import { cmd, openNote, sleep, key } from "./lib.mjs";

const TA = ".modal-container textarea[placeholder]";
const POP = ".modal-container .suggestion-container";

const geom = ({ client, json }) =>
  client.evaluate(`
    const ta = document.querySelectorAll(${json(".modal-container textarea")});
    const t = [...ta].find((el) => !el.readOnly && !el.className.includes("cursor-default")) || ta[ta.length - 1];
    const p = document.querySelector(${json(POP)});
    const tr = t?.getBoundingClientRect(); const pr = p?.getBoundingClientRect();
    return { hasTa: !!t, taH: t?.offsetHeight, taStyleH: t?.style.height, scrollH: t?.scrollHeight,
      pop: !!p, popPos: p && getComputedStyle(p).position,
      dTop: p && Math.round(pr.top - tr.bottom), dLeft: p && Math.round(pr.left - tr.left), dW: p && Math.round(pr.width - tr.width),
      items: p ? p.querySelectorAll(".suggestion-item").length : 0 };`);

const typeInTitle = async ({ client, json }, text) => {
  await client.evaluate(`
    const ta = [...document.querySelectorAll(${json(".modal-container textarea")})].find((el) => el.className.includes("bg-background-primary"));
    ta.focus(); return true;`);
  await client.typeText(text);
};

const openCreate = async (ctx, body, sel) => {
  const p = await ctx.writeNote("modal-scratch.md", body);
  await openNote(ctx, p, sel);
  await cmd(ctx, "create-discourse-node");
  await ctx.client.waitFor(`!!document.querySelector(${ctx.json(".modal-container textarea")})`, { label: "modal open" });
  await sleep(300);
};

export default [
  {
    name: "T2.1 popover sits under title",
    input: "Create discourse node (empty selection); type 'test'",
    expected: "popover position:fixed, top = textarea bottom + 8 (4px offset + mt-1, main baseline), same left/width",
    run: async (ctx) => {
      await openCreate(ctx, "scratch\n");
      await typeInTitle(ctx, "test");
      await ctx.client.waitFor(`!!document.querySelector(${ctx.json(POP)})`, { label: "popover" });
      await sleep(400);
      return geom(ctx);
    },
    expect: (a) => ({ pass: a.pop && a.popPos === "fixed" && a.dTop === 8 && a.dLeft === 0 && a.dW === 0, actual: JSON.stringify(a) }),
  },
  {
    name: "T2.2 popover follows grown textarea",
    input: "Create discourse node; type 'test'; insert 3 newlines",
    expected: "PARITY with main: textarea grows (height == scrollHeight); popover stays at old position, overlapping by 17px (pre-existing bug)",
    run: async (ctx) => {
      await openCreate(ctx, "scratch\n");
      await typeInTitle(ctx, "test");
      await ctx.client.waitFor(`!!document.querySelector(${ctx.json(POP)})`, { label: "popover" });
      const before = await geom(ctx);
      await ctx.client.send("Input.insertText", { text: "\n\n\n" });
      await sleep(600);
      return { before, after: await geom(ctx) };
    },
    expect: (a) => ({
      pass: a.after.taH > a.before.taH && Math.abs(parseInt(a.after.taStyleH) - a.after.scrollH) <= 2 && a.after.pop && a.after.dTop === -17 && a.after.dLeft === 0,
      actual: JSON.stringify(a),
    }),
  },
  {
    name: "T2.4 no popover in convert-current-page",
    input: "Convert current page to discourse node; type 'test'",
    expected: "no .suggestion-container",
    run: async (ctx) => {
      const p = await ctx.writeNote("convert-scratch.md", "body\n");
      await openNote(ctx, p);
      await cmd(ctx, "convert-current-page-to-discourse-node");
      await ctx.client.waitFor(`!!document.querySelector(".modal-container textarea")`, { label: "modal open" });
      await typeInTitle(ctx, " test");
      await sleep(800);
      return geom(ctx);
    },
    expect: (a) => ({ pass: a.hasTa && !a.pop, actual: JSON.stringify(a) }),
  },
  {
    name: "T2.5 auto-height on open with long selection, shrinks on delete",
    input: "Select a 300-char line; Create discourse node; then select-all + type 'x'",
    expected: "on open height == scrollHeight (multi-row); after replace it shrinks",
    run: async (ctx) => {
      const line = "word ".repeat(60).trim();
      await openCreate(ctx, line + "\n", { selectFrom: { line: 0, ch: 0 }, selectTo: { line: 0, ch: line.length } });
      const open = await geom(ctx);
      await ctx.client.evaluate(`
        const ta = [...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary"));
        ta.focus(); ta.select(); return true;`);
      await ctx.client.typeText("x");
      await sleep(400);
      return { open, after: await geom(ctx) };
    },
    expect: (a) => ({
      pass: a.open.taH > 60 && Math.abs(parseInt(a.open.taStyleH) - a.open.scrollH) <= 2 && a.after.taH < a.open.taH,
      actual: `open h=${a.open.taH} style=${a.open.taStyleH} scroll=${a.open.scrollH}; after h=${a.after.taH}`,
    }),
  },
  {
    name: "T2.6 keyboard pick from popover",
    input: "Create discourse node; type 'test'; ArrowDown; Enter",
    expected: "item picked: textarea replaced by locked display, popover gone",
    run: async (ctx) => {
      await openCreate(ctx, "scratch\n");
      await typeInTitle(ctx, "test");
      await ctx.client.waitFor(`document.querySelectorAll(${ctx.json(POP + " .suggestion-item")}).length > 0`, { label: "items" });
      await sleep(300);
      await ctx.client.key(key("ArrowDown", "ArrowDown", 40));
      await ctx.client.key(key("Enter", "Enter", 13));
      await sleep(500);
      return ctx.client.evaluate(`return {
        pop: !!document.querySelector(${ctx.json(POP)}),
        titleTa: !![...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary")),
        text: document.querySelector(".modal-container .modal-content")?.innerText.slice(0, 200) };`);
    },
    expect: (a) => ({ pass: !a.pop && !a.titleTa, actual: JSON.stringify(a) }),
  },
];
import modal from "./s-modal.mjs";
import sidebar from "./s-sidebar.mjs";
import schema from "./s-schema.mjs";
import canvas from "./s-canvas.mjs";
import { recorded } from "./rec.mjs";
export default [
  ...recorded(modal, { prefix: "a2-modal" }),
