// Helpers for the PR #1627 behaviour scenarios (P*). Own state file so other canvas runs don't clash.
import fs from "node:fs";
import { cmd, sleep, move, mouse, key } from "./lib.mjs";
import { grabEditor, collapse, NT, fm } from "./canvaslib.mjs";

const STATE = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/dad56eb0-85c8-43af-afe3-79e3dc24c31b/scratchpad/cdp/p-state.json";
export const readP = () => (fs.existsSync(STATE) ? JSON.parse(fs.readFileSync(STATE, "utf8")) : {});
export const writeP = (s) => fs.writeFileSync(STATE, JSON.stringify(s, null, 2));
export { NT, fm, sleep, move, mouse, key, cmd };

export const IMG = "Pasted image 20250226085511.png";

// Node notes used across scenarios. Written once: relations add nodeInstanceId to their frontmatter.
export const ensureNodes = async (ctx) => {
  const { client, json } = ctx;
  const out = {};
  for (const [k, name, type] of [["ev", "pr-ev-node.md", NT.evidence], ["cl", "pr-cl-node.md", NT.claim], ["cl2", "pr-cl2-node.md", NT.claim]]) {
    const p = ctx.verifyPath(name);
    const exists = await client.evaluate(`return !!app.vault.getAbstractFileByPath(${json(p)});`);
    out[k] = exists ? p : await ctx.writeNote(name, fm(type, `${k} body`));
  }
  return out;
};

export const rclick = async ({ client }, x, y) => {
  await client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y, button: "none", buttons: 0 });
  await client.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "right", buttons: 2, clickCount: 1 });
  await client.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "right", buttons: 0, clickCount: 1 });
};

export const hover = ({ client }, x, y) => client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y, button: "none", buttons: 0 });

export const clickAt = async (ctx, x, y) => {
  await hover(ctx, x, y);
  await mouse(ctx, "mousePressed", x, y);
  await mouse(ctx, "mouseReleased", x, y);
};

// Centre of the element matched by a JS expression returning an Element.
export const rectOf = ({ client }, elExpr) =>
  client.evaluate(`const el = (() => { ${elExpr} })(); if (!el) return null; const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2, w: r.width, h: r.height };`);

// Obsidian Menu item by title, searching the most recently opened menus first.
const obsMenuItem = (title) => `const t = ${JSON.stringify(title)};
  const menus = [...document.querySelectorAll(".menu")].reverse();
  for (const m of menus) { const it = [...m.querySelectorAll(".menu-item")].find((i) => i.querySelector(".menu-item-title")?.textContent.trim() === t); if (it) return it; }
  return null;`;

export const obsMenuPick = async (ctx, path) => {
  const { client } = ctx;
  for (let i = 0; i < path.length; i++) {
    await client.waitFor(`return !!(() => { ${obsMenuItem(path[i])} })()`, { label: `menu item ${path[i]}`, timeoutMs: 5000 });
    const r = await rectOf(ctx, obsMenuItem(path[i]));
    if (i < path.length - 1) {
      await hover(ctx, r.x - 10, r.y);
      await hover(ctx, r.x, r.y);
      await sleep(500);
    } else await clickAt(ctx, r.x, r.y);
  }
};

// tldraw UI menu button by visible label.
const tlMenuItem = (label) => `const t = ${JSON.stringify(label)};
  return [...document.querySelectorAll(".tlui-menu button, [data-radix-popper-content-wrapper] button")].reverse().find((b) => (b.querySelector(".tlui-button__label")?.textContent ?? b.textContent).trim() === t) ?? null;`;

export const tlMenuPick = async (ctx, path) => {
  const { client } = ctx;
  for (let i = 0; i < path.length; i++) {
    await client.waitFor(`return !!(() => { ${tlMenuItem(path[i])} })()`, { label: `tl menu item ${path[i]}`, timeoutMs: 5000 });
    const r = await rectOf(ctx, tlMenuItem(path[i]));
    if (i < path.length - 1) {
      await hover(ctx, r.x - 10, r.y);
      await hover(ctx, r.x, r.y);
      await sleep(300);
      const open = await client.evaluate(`return !!(() => { ${tlMenuItem(path[i + 1])} })();`);
      if (!open) await clickAt(ctx, r.x, r.y);
      await sleep(300);
    } else await clickAt(ctx, r.x, r.y);
  }
};

// Modal title textarea, type select, popover geometry.
const TITLE = `[...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary"))`;
export const modalState = ({ client }) =>
  client.evaluate(`
    const t = ${TITLE};
    const p = document.querySelector(".modal-container .suggestion-container");
    const sel = document.querySelector(".modal-container select");
    const tr = t?.getBoundingClientRect(); const pr = p?.getBoundingClientRect();
    return { modal: !!document.querySelector(".modal-container"), hasTa: !!t, title: t?.value ?? null, placeholder: t?.placeholder ?? null,
      type: sel ? (sel.options[sel.selectedIndex]?.text ?? "") : null,
      pop: !!p, popPos: p ? getComputedStyle(p).position : null,
      dTop: p ? Math.round(pr.top - tr.bottom) : null, dLeft: p ? Math.round(pr.left - tr.left) : null,
      items: p ? [...p.querySelectorAll(".suggestion-item")].map((li) => li.textContent.trim().slice(0, 40)).slice(0, 4) : [] };`);

export const waitModal = ({ client }) =>
  client.waitFor(`return !!(${TITLE})`, { label: "node modal title textarea", timeoutMs: 6000 });

// Real click on the title, select all, type.
export const typeTitle = async (ctx, text) => {
  const { client } = ctx;
  const r = await rectOf(ctx, `return ${TITLE};`);
  await clickAt(ctx, r.x, r.y);
  await client.key(key("KeyA", "a", 65, { modifiers: 4, commands: ["selectAll"] }));
  await client.typeText(text);
};

export const waitPopover = ({ client }) =>
  client
    .waitFor(`return document.querySelectorAll(".modal-container .suggestion-container .suggestion-item").length > 0 && !/Searching/.test(document.querySelector(".modal-container .suggestion-container").textContent)`, { label: "popover", timeoutMs: 8000 })
    .then(() => true, () => false);

export const popoverOk = (g) => g.pop && g.popPos === "fixed" && g.dTop === 8 && g.dLeft === 0;

export const openLP = ({ client, json }, path, mode = "source") =>
  client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(path)}), { state: { mode: ${json(mode)}, source: false } });
    app.workspace.setActiveLeaf(leaf, { focus: true }); return true; })();`);

// Canvas: reopen a saved canvas by state key.
export const openPCanvas = async (ctx, which = "canvas") => {
  const { client, json } = ctx;
  const st = readP();
  if (!st[which]) throw new Error(`no ${which}: run P0 first`);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.setViewState({ type: ${json(st.viewType)}, state: { file: ${json(st[which])} }, active: true });
    app.workspace.setActiveLeaf(leaf, { focus: true }); return true; })();`);
  await client.waitFor(`return !!app.workspace.activeLeaf?.view?.containerEl.querySelector(".tl-canvas")`, { label: "canvas view" });
  await collapse(ctx);
  await sleep(700);
  await grabEditor(ctx);
  await client.evaluate(`const ed = window.__dgEditor; ed.setCurrentTool("select"); ed.selectNone(); return true;`);
  return st;
};

export const newCanvas = async (ctx) => {
  const { client } = ctx;
  await cmd(ctx, "create-discourse-graph-canvas");
  await client.waitFor(`return !!app.workspace.activeLeaf?.view?.containerEl.querySelector(".tl-canvas")`, { label: "canvas view" });
  await collapse(ctx);
  await sleep(700);
  await grabEditor(ctx);
  return {
    path: await client.evaluate(`return app.workspace.activeLeaf.view.file.path;`),
    viewType: await client.evaluate(`return app.workspace.activeLeaf.view.getViewType();`),
  };
};

export const bindingsOf = ({ client, json }, rel) =>
  client.evaluate(`return window.__dgEditor.getBindingsFromShape(${json(rel)}, "discourse-relation").map((b) => ({ terminal: b.props.terminal, toId: b.toId }));`);

export const shapeById = ({ client, json }, id) =>
  client.evaluate(`const s = window.__dgEditor.getShape(${json(id)}); return s ? { id: s.id, type: s.type, x: s.x, y: s.y, index: s.index, parentId: s.parentId, props: s.props, meta: s.meta } : null;`);

export const pageCounts = ({ client }) =>
  client.evaluate(`const ed = window.__dgEditor; const sh = ed.getCurrentPageShapes();
    const by = {}; sh.forEach((s) => { by[s.type] = (by[s.type] || 0) + 1; });
    const rels = sh.filter((s) => s.type === "discourse-relation");
    const binds = rels.reduce((n, r) => n + ed.getBindingsFromShape(r.id, "discourse-relation").length, 0);
    return { by, relBindings: binds, relIds: rels.map((r) => r.id) };`);

// Wait until a shape's w/h/title stop changing.
export const settle = async ({ client, json }, id, quietMs = 1500) => {
  let last = "", since = Date.now();
  const end = Date.now() + 10000;
  while (Date.now() < end) {
    const cur = await client.evaluate(`const s = window.__dgEditor.getShape(${json(id)}); return s ? s.props.w + "x" + s.props.h + ":" + s.props.title : "";`);
    if (cur !== last) { last = cur; since = Date.now(); } else if (Date.now() - since > quietMs) return cur;
    await sleep(250);
  }
  return last;
};

export const centerOfShape = ({ client, json }, id) =>
  client.evaluate(`const ed = window.__dgEditor; const b = ed.getShapePageBounds(${json(id)}); const s = ed.pageToScreen({ x: b.midX, y: b.midY }); return { x: s.x, y: s.y };`);

// Midpoint of a relation's path (start/end in page space), as screen point.
export const relMid = ({ client, json }, id) =>
  client.evaluate(`const ed = window.__dgEditor; const r = ed.getShape(${json(id)}); const t = ed.getShapePageTransform(r);
    const a = t.applyToPoint(r.props.start), b = t.applyToPoint(r.props.end); const s = ed.pageToScreen({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }); return { x: s.x, y: s.y };`);

export const trapErrors = ({ client }) =>
  client.evaluate(`window.__pErr = []; if (!window.__pOrigErr) window.__pOrigErr = console.error;
    console.error = (...a) => { window.__pErr.push(a.map(String).join(" ").slice(0, 200)); window.__pOrigErr(...a); };
    window.__pOnErr = (e) => window.__pErr.push("uncaught: " + (e.message || e.reason)); window.addEventListener("error", window.__pOnErr); window.addEventListener("unhandledrejection", window.__pOnErr); return true;`);
export const releaseErrors = ({ client }) =>
  client.evaluate(`if (window.__pOrigErr) console.error = window.__pOrigErr; window.removeEventListener("error", window.__pOnErr); window.removeEventListener("unhandledrejection", window.__pOnErr);
    return (window.__pErr || []).filter((e) => !/ResizeObserver|Not logged in/.test(e));`);

export const cmdKey = (code, k, vk, extra = {}) => key(code, k, vk, { modifiers: 4, ...extra });

