// P1-P6: every ModifyNodeModal entry point, driven by real input.
import { openNote } from "./lib.mjs";
import {
  ensureNodes, rclick, hover, clickAt, rectOf, obsMenuPick, tlMenuPick, modalState, waitModal, typeTitle, waitPopover, popoverOk,
  openLP, openPCanvas, centerOfShape, sleep, key, IMG,
} from "./p-lib.mjs";

const selMid = ({ client }) =>
  client.evaluate(`const ed = app.workspace.activeLeaf.view.editor; const a = ed.posToOffset(ed.getCursor("from")), b = ed.posToOffset(ed.getCursor("to"));
    const c = ed.cm.coordsAtPos(Math.round((a + b) / 2)); return { x: c.left, y: (c.top + c.bottom) / 2, sel: ed.getSelection() };`);

const popoverExpect = (title, type) => (a) => ({
  pass: a.open.hasTa && a.open.title === title && (type === null || a.open.type === type) && a.found && popoverOk(a.after),
  actual: JSON.stringify(a),
});

const typeAndRead = async (ctx, text, { expectPopover }) => {
  await typeTitle(ctx, text);
  const found = expectPopover ? await waitPopover(ctx) : (await sleep(1500), false);
  await sleep(300);
  return { found, after: await modalState(ctx) };
};

export default [
  {
    name: "P1 editor right-click → Turn into discourse node",
    input: "select 'selected words' in a note; right-click it; Turn into discourse node → Evidence; type 'pr-ev'",
    expected: "modal opens, title = selection, type Evidence; popover fixed, dTop 8, dLeft 0 under title",
    run: async (ctx) => {
      await ensureNodes(ctx);
      const p = await ctx.writeNote("p1-host.md", "alpha selected words omega\n");
      await openNote(ctx, p, { selectFrom: { line: 0, ch: 6 }, selectTo: { line: 0, ch: 20 } });
      await sleep(400);
      const m = await selMid(ctx);
      await rclick(ctx, m.x, m.y);
      await obsMenuPick(ctx, ["Turn into discourse node", "Evidence"]);
      await waitModal(ctx);
      const open = await modalState(ctx);
      return { sel: m.sel, open, ...(await typeAndRead(ctx, "pr-ev", { expectPopover: true })) };
    },
    expect: popoverExpect("selected words", "Evidence"),
  },
  {
    name: "P2 node-tag hotkey → inline type picker",
    input: "select 'picked phrase'; press \\ (Node tag hotkey); click Evidence in the picker; type 'pr-ev'",
    expected: "picker opens; modal title = selection, type Evidence; popover fixed, dTop 8, dLeft 0",
    run: async (ctx) => {
      const { client } = ctx;
      await ensureNodes(ctx);
      const p = await ctx.writeNote("p2-host.md", "some picked phrase here\n");
      await openNote(ctx, p, { selectFrom: { line: 0, ch: 5 }, selectTo: { line: 0, ch: 18 } });
      await sleep(400);
      const hot = await client.evaluate(`return app.plugins.plugins["@discourse-graph/obsidian"].settings.nodeTagHotkey;`);
      await client.key({ key: hot, code: "Backslash", windowsVirtualKeyCode: 220, nativeVirtualKeyCode: 220, text: hot });
      await client.waitFor(`return document.querySelectorAll(".inline-node-type-item").length > 0`, { label: "inline picker", timeoutMs: 4000 });
      await sleep(300);
      const items = await client.evaluate(`return [...document.querySelectorAll(".inline-node-type-item")].map((e) => e.textContent.trim());`);
      const r = await rectOf(ctx, `return [...document.querySelectorAll(".inline-node-type-item")].find((e) => e.textContent.trim() === "Evidence");`);
      await clickAt(ctx, r.x, r.y);
      await waitModal(ctx);
      const open = await modalState(ctx);
      return { hot, items, open, ...(await typeAndRead(ctx, "pr-ev", { expectPopover: true })) };
    },
    expect: popoverExpect("picked phrase", "Evidence"),
  },
  {
    name: "P3 hover node tag → Create Evidence",
    input: "Live Preview line 'tagged line text #evd-candidate'; hover the tag; click 'Create Evidence'; type 'pr-ev'",
    expected: "tooltip button 'Create Evidence'; modal title = line text, type Evidence; popover fixed, dTop 8, dLeft 0",
    run: async (ctx) => {
      const { client } = ctx;
      await ensureNodes(ctx);
      const p = await ctx.writeNote("p3-host.md", "tagged line text #evd-candidate\n");
      await openLP(ctx, p);
      await client.waitFor(`return !!app.workspace.activeLeaf.view.containerEl.querySelector(".dg-discourse-tag")`, { label: "tag chip", timeoutMs: 5000 });
      await sleep(400);
      const t = await rectOf(ctx, `return app.workspace.activeLeaf.view.containerEl.querySelector(".dg-discourse-tag");`);
      await hover(ctx, t.x - 60, t.y + 40);
      await hover(ctx, t.x, t.y);
      await client.waitFor(`return !!document.querySelector(".discourse-tag-popover button")`, { label: "tag tooltip", timeoutMs: 4000 });
      await sleep(300);
      const label = await client.evaluate(`return document.querySelector(".discourse-tag-popover button").textContent;`);
      const b = await rectOf(ctx, `return document.querySelector(".discourse-tag-popover button");`);
      await hover(ctx, b.x, b.y);
      await clickAt(ctx, b.x, b.y);
      await waitModal(ctx);
      const open = await modalState(ctx);
      return { label, open, ...(await typeAndRead(ctx, "pr-ev", { expectPopover: true })) };
    },
    expect: (a) => ({ ...popoverExpect("tagged line text", "Evidence")(a), pass: a.label === "Create Evidence" && popoverExpect("tagged line text", "Evidence")(a).pass }),
  },
  {
    name: "P4 hover image embed → Convert to node",
    input: `Live Preview note embedding ![[${IMG}]]; hover the image; click the Convert to node icon; type 'pr-ev'`,
    expected: "modal opens with empty title (no type preset); popover fixed, dTop 8, dLeft 0",
    run: async (ctx) => {
      const { client } = ctx;
      await ensureNodes(ctx);
      const p = await ctx.writeNote("p4-host.md", `image below\n\n![[${IMG}]]\n\nafter\n`);
      await openLP(ctx, p);
      await client.waitFor(`return !!app.workspace.activeLeaf.view.containerEl.querySelector(".internal-embed.image-embed .dg-image-convert-icon")`, { label: "convert icon", timeoutMs: 6000 });
      await sleep(500);
      const e = await rectOf(ctx, `return app.workspace.activeLeaf.view.containerEl.querySelector(".internal-embed.image-embed img") || app.workspace.activeLeaf.view.containerEl.querySelector(".internal-embed.image-embed");`);
      await hover(ctx, e.x, e.y);
      await sleep(500);
      const icon = await client.evaluate(`const i = app.workspace.activeLeaf.view.containerEl.querySelector(".dg-image-convert-icon"); const r = i.getBoundingClientRect(); const cs = getComputedStyle(i);
        return { x: r.left + r.width / 2, y: r.top + r.height / 2, w: r.width, opacity: cs.opacity, display: cs.display, tip: i.getAttribute("aria-label") };`);
      await hover(ctx, icon.x, icon.y);
      await clickAt(ctx, icon.x, icon.y);
      await waitModal(ctx);
      const open = await modalState(ctx);
      return { icon, open, ...(await typeAndRead(ctx, "pr-ev", { expectPopover: true })) };
    },
    expect: (a) => ({ pass: a.icon.w > 0 && a.icon.opacity !== "0" && popoverExpect("", null)(a).pass, actual: JSON.stringify(a) }),
  },
  {
    name: "P5a file explorer note → Convert into Claim",
    input: "right-click a plain note in the file explorer; Convert into → Claim; type 'pr-cl'; then Escape",
    expected: "modal opens, title = basename, type Claim; no popover (search disabled)",
    run: async (ctx) => {
      const { client, json } = ctx;
      await ensureNodes(ctx);
      const p = await ctx.writeNote("p5-plain.md", "plain note body\n");
      await sleep(500);
      await client.evaluate(`return (async () => { app.workspace.leftSplit.expand();
        let leaf = app.workspace.getLeavesOfType("file-explorer")[0]; app.workspace.revealLeaf(leaf);
        leaf.view.revealInFolder(app.vault.getAbstractFileByPath(${json(p)})); return true; })();`);
      await client.waitFor(`return !!document.querySelector('.nav-file-title[data-path=${json(p).replace(/"/g, '\\"')}]')`, { label: "explorer row" });
      await sleep(600);
      const r = await rectOf(ctx, `return document.querySelector('.nav-file-title[data-path=${json(p).replace(/"/g, '\\"')}]');`);
      await rclick(ctx, r.x, r.y);
      await obsMenuPick(ctx, ["Convert into", "Claim"]);
      await waitModal(ctx);
      const open = await modalState(ctx);
      const res = await typeAndRead(ctx, "pr-cl", { expectPopover: false });
      await client.pressEscape();
      await sleep(300);
      const fileKept = await client.evaluate(`return !app.metadataCache.getFileCache(app.vault.getAbstractFileByPath(${json(p)}))?.frontmatter?.nodeTypeId;`);
      return { open, ...res, fileKept };
    },
    expect: (a) => ({ pass: a.open.hasTa && a.open.title === "p5-plain" && a.open.type === "Claim" && !a.after.pop && a.after.title === "pr-cl" && a.fileKept, actual: JSON.stringify(a) }),
  },
  {
    name: "P5b file explorer image → Convert into Evidence",
    input: `right-click ${IMG} in the file explorer; Convert into → Evidence; type 'pr-ev'; then Escape`,
    expected: "modal opens, empty title, type Evidence; no popover (search disabled)",
    run: async (ctx) => {
      const { client, json } = ctx;
      await client.evaluate(`return (async () => { app.workspace.leftSplit.expand();
        let leaf = app.workspace.getLeavesOfType("file-explorer")[0]; app.workspace.revealLeaf(leaf);
        leaf.view.revealInFolder(app.vault.getAbstractFileByPath(${json(IMG)})); return true; })();`);
      await client.waitFor(`return !!document.querySelector('.nav-file-title[data-path=${json(IMG).replace(/"/g, '\\"')}]')`, { label: "explorer image row" });
      await sleep(600);
      const r = await rectOf(ctx, `return document.querySelector('.nav-file-title[data-path=${json(IMG).replace(/"/g, '\\"')}]');`);
      await rclick(ctx, r.x, r.y);
      await obsMenuPick(ctx, ["Convert into", "Evidence"]);
      await waitModal(ctx);
      const open = await modalState(ctx);
      const res = await typeAndRead(ctx, "pr-ev", { expectPopover: false });
      await client.pressEscape();
      return { open, ...res };
    },
    expect: (a) => ({ pass: a.open.hasTa && a.open.title === "" && a.open.type === "Evidence" && !a.after.pop && a.after.title === "pr-ev", actual: JSON.stringify(a) }),
  },
  {
    name: "P6a canvas text shape → Convert To Evidence",
    input: "canvas text shape 'pr canvas text'; right-click it; Convert To → Evidence; type 'pr-ev'",
    expected: "modal title = shape text, type Evidence; popover fixed, dTop 8, dLeft 0",
    run: async (ctx, state) => {
      const { client } = ctx;
      await openPCanvas(ctx);
      state.id = await client.evaluate(`const ed = window.__dgEditor; const vp = ed.getViewportPageBounds(); const id = "shape:prtext" + Date.now();
        ed.createShape({ id, type: "text", x: vp.x + vp.w * 0.15, y: vp.y + vp.h * 0.15,
          props: { richText: { type: "doc", content: [{ type: "paragraph", content: [{ type: "text", text: "pr canvas text" }] }] } } });
        ed.select(id); return id;`);
      await sleep(500);
      const c = await centerOfShape(ctx, state.id);
      await rclick(ctx, c.x, c.y);
      await tlMenuPick(ctx, ["Convert To", "Evidence"]);
      await waitModal(ctx);
      const open = await modalState(ctx);
      return { open, ...(await typeAndRead(ctx, "pr-ev", { expectPopover: true })) };
    },
    setup: async () => ({}),
    expect: popoverExpect("pr canvas text", "Evidence"),
    teardown: async ({ client, json }, state) => {
      await client.pressEscape();
      if (state.id) await client.evaluate(`window.__dgEditor?.deleteShapes([${json(state.id)}]); return true;`);
    },
  },
  {
    name: "P6b canvas image shape → Convert To Claim",
    input: `canvas image shape of ${IMG}; right-click it; Convert To → Claim; type 'pr-cl'`,
    expected: "modal with empty title, type Claim; popover fixed, dTop 8, dLeft 0",
    setup: async () => ({}),
    run: async (ctx, state) => {
      const { client, json } = ctx;
      await openPCanvas(ctx);
      Object.assign(state, await client.evaluate(`const ed = window.__dgEditor; const vp = ed.getViewportPageBounds(); const n = Date.now();
        const assetId = "asset:primg" + n, id = "shape:primg" + n;
        const src = app.vault.getResourcePath(app.vault.getAbstractFileByPath(${json(IMG)}));
        ed.createAssets([{ id: assetId, typeName: "asset", type: "image", meta: {}, props: { name: ${json(IMG)}, src, w: 240, h: 160, mimeType: "image/png", isAnimated: false } }]);
        ed.createShape({ id, type: "image", x: vp.x + vp.w * 0.12, y: vp.y + vp.h * 0.1, props: { assetId, w: 240, h: 160 } });
        ed.select(id); return { id, assetId };`));
      await sleep(600);
      const c = await centerOfShape(ctx, state.id);
      await rclick(ctx, c.x, c.y);
      await tlMenuPick(ctx, ["Convert To", "Claim"]);
      await waitModal(ctx);
      const open = await modalState(ctx);
      return { open, ...(await typeAndRead(ctx, "pr-cl", { expectPopover: true })) };
    },
    expect: popoverExpect("", "Claim"),
    teardown: async ({ client, json }, state) => {
      await client.pressEscape();
      if (state.id) await client.evaluate(`const ed = window.__dgEditor; ed?.deleteShapes([${json(state.id)}]); ed?.deleteAssets([${json(state.assetId)}]); return true;`);
    },
  },
];

