        leaf.view.revealInFolder(app.vault.getAbstractFileByPath(${json(p)})); return true; })();`);
      await client.waitFor(`return !!document.querySelector('.nav-file-title[data-path=${json(p).replace(/"/g, '\\"')}]')`, { label: "explorer row" });
