      await obsMenuPick(ctx, ["Convert into", "Evidence"]);
      await waitModal(ctx);
      const open = await modalState(ctx);
      const res = await typeAndRead(ctx, "pr-ev", { expectPopover: false });
      await client.pressEscape();
      return { open, ...res };
