        const assetId = "asset:primg" + n, id = "shape:primg" + n;
        const src = app.vault.getResourcePath(app.vault.getAbstractFileByPath(${json(IMG)}));
        ed.createAssets([{ id: assetId, typeName: "asset", type: "image", meta: {}, props: { name: ${json(IMG)}, src, w: 240, h: 160, mimeType: "image/png", isAnimated: false } }]);
        ed.createShape({ id, type: "image", x: vp.x + vp.w * 0.12, y: vp.y + vp.h * 0.1, props: { assetId, w: 240, h: 160 } });
        ed.select(id); return { id, assetId };`));
      await sleep(600);
      const c = await centerOfShape(ctx, state.id);
