// P7: wikilink relation-count badge popover in Reading view.
import { ensureNodes, openLP, rectOf, clickAt, sleep } from "./p-lib.mjs";

const POP = ".dg-discourse-context-popover";

export default [
  {
    name: "P7 Reading-view badge popover → Add a new relation chips",
    input: "Reading view note linking [[pr-ev-node]]; click its badge; click 'Add a new relation'; pick 'informs' in the type select",
    expected: "badge rendered in reading view; popover opens; chips 'You can link with' = [Question]",
    run: async (ctx) => {
      const { client } = ctx;
      await ensureNodes(ctx);
      const p = await ctx.writeNote("p7-link-host.md", "see [[pr-ev-node]] here\n");
      await openLP(ctx, p, "preview");
      const hasBadge = await client
        .waitFor(`return !!app.workspace.activeLeaf.view.containerEl.querySelector(".markdown-reading-view .dg-discourse-context-badge")`, { label: "reading badge", timeoutMs: 6000 })
        .then(() => true, () => false);
      if (!hasBadge) return { hasBadge };
      await sleep(400);
      const mode = await client.evaluate(`return app.workspace.activeLeaf.view.getMode();`);
      const b = await rectOf(ctx, `return app.workspace.activeLeaf.view.containerEl.querySelector(".markdown-reading-view .dg-discourse-context-badge");`);
      await clickAt(ctx, b.x, b.y);
      await client.waitFor(`return !!document.querySelector(${JSON.stringify(POP)})`, { label: "popover", timeoutMs: 5000 });
      await sleep(500);
      const add = await rectOf(ctx, `return [...document.querySelectorAll(${JSON.stringify(POP + " button")})].find((x) => x.textContent.trim() === "Add a new relation");`);
      await clickAt(ctx, add.x, add.y);
      await client.waitFor(`return !!document.querySelector(${JSON.stringify(POP + " .relationship-type-selector select")})`, { label: "type select" });
      await sleep(400);
      const before = await client.evaluate(`const root = document.querySelector(${JSON.stringify(POP)}); return !![...root.querySelectorAll("span")].find((s) => s.textContent.startsWith("You can link with"));`);
      // Native <select> popups can't be driven over CDP; set the value and fire change like a pick.
      await client.evaluate(`const sel = document.querySelector(${JSON.stringify(POP + " .relationship-type-selector select")});
        sel.focus(); sel.value = "informs"; sel.dispatchEvent(new Event("change", { bubbles: true })); return true;`);
      await sleep(600);
      const chips = await client.evaluate(`const root = document.querySelector(${JSON.stringify(POP)});
        const hint = [...root.querySelectorAll("span")].find((s) => s.textContent.startsWith("You can link with"));
        return hint ? [...hint.querySelectorAll("span")].map((s) => s.textContent) : [];`);
      return { hasBadge, mode, hintBefore: before, chips };
    },
    expect: (a) => ({ pass: a.hasBadge && a.mode === "preview" && !a.hintBefore && a.chips?.join() === "Question", actual: JSON.stringify(a) }),
    teardown: async ({ client }) => client.evaluate(`document.querySelectorAll(".dg-discourse-context-popover").forEach((e) => e.remove()); return true;`),
  },
];

