// P0 fixture + P8-P18 canvas behaviour (node shape load effect, relation shape, binding, export).
import { dropNode } from "./canvaslib.mjs";
import {
  ensureNodes, readP, writeP, openPCanvas, newCanvas, NT, fm, sleep, move, mouse, key, cmdKey, rclick, hover, clickAt, rectOf,
  tlMenuPick, obsMenuPick, bindingsOf, shapeById, pageCounts, settle, centerOfShape, relMid, trapErrors, releaseErrors,
} from "./p-lib.mjs";

const REL = { supports: "relation_uQaqcnuWonKQ7xTjt4OiF", opposes: "relation_QwIpv1Clefkk76KoGqolU" };
const raf2 = `await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));`;

const drag = async (ctx, a, b, steps = 12) => {
  await move(ctx, a.x, a.y, false);
  await mouse(ctx, "mousePressed", a.x, a.y);
  for (let i = 1; i <= steps; i++) await move(ctx, a.x + ((b.x - a.x) * i) / steps, a.y + ((b.y - a.y) * i) / steps);
  await mouse(ctx, "mouseReleased", b.x, b.y);
};

const dropAt = async (ctx, path, fx, fy) => {
  const vp = await ctx.client.evaluate(`const b = window.__dgEditor.getViewportPageBounds(); return { x: b.x, y: b.y, w: b.w, h: b.h };`);
  await dropNode(ctx, path, { x: vp.x + vp.w * fx, y: vp.y + vp.h * fy });
};

const nodeByTitle = ({ client, json }, title) =>
  client.evaluate(`const s = window.__dgEditor.getCurrentPageShapes().find((s) => s.type === "discourse-node" && s.props.title === ${json(title)}); return s ? s.id : null;`);

// Indicator child tags for one shape (as s-canvas indicatorSig, scoped to the shape when tagged).
const indicatorOf = ({ client, json }, id) =>
  client.evaluate(`return (async () => { ${raf2}
    const root = app.workspace.activeLeaf.view.containerEl;
    const gs = [...root.querySelectorAll("g.tl-shape-indicator")];
    const mine = gs.filter((g) => g.closest("[data-shape-id]")?.getAttribute("data-shape-id") === ${json(id)} || g.getAttribute("data-shape-id") === ${json(id)});
    return (mine.length ? mine : gs).map((g) => [...g.querySelectorAll("*")].map((e) => e.tagName).join(",")); })();`);

const mark = ({ client, json }, m) => client.evaluate(`window.__dgEditor.markHistoryStoppingPoint(${json(m)}); return true;`);
const bail = ({ client, json }, m) => client.evaluate(`window.__dgEditor?.bailToMark(${json(m)}); return true;`);

const ensureRelReady = async (ctx) => {
  const st = await openPCanvas(ctx);
  const ok = await ctx.client.evaluate(`const ed = window.__dgEditor; return [${JSON.stringify(st.ev)}, ${JSON.stringify(st.cl)}, ${JSON.stringify(st.cl2)}, ${JSON.stringify(st.rel)}].every((id) => !!ed.getShape(id));`);
  if (!ok) throw new Error("P canvas fixture shapes missing: rerun P0");
  return st;
};

// Duplicate / copy-paste probe shared by P16 and P17.
const dupProbe = async (ctx, st, { bend }) => {
  const { client, json } = ctx;
  await mark(ctx, "p-dup");
  if (bend) await client.evaluate(`window.__dgEditor.updateShape({ id: ${json(st.rel)}, type: "discourse-relation", props: { bend: ${bend} } }); return true;`);
  await sleep(300);
  await trapErrors(ctx);
  const c0 = await pageCounts(ctx);
  const m = await relMid(ctx, st.rel);
  await clickAt(ctx, m.x, m.y);
  await sleep(300);
  const selected = await client.evaluate(`return window.__dgEditor.getSelectedShapeIds();`);
  await client.key(cmdKey("KeyD", "d", 68, { commands: [] }));
  await sleep(900);
  const c1 = await pageCounts(ctx);
  const dupId = c1.relIds.find((id) => !c0.relIds.includes(id));
  const dupBinds = dupId ? await bindingsOf(ctx, dupId) : null;
  // Copy relation + only its start node, then paste.
  await client.evaluate(`window.__dgEditor.select(${json(st.rel)}, ${json(st.ev)}); return true;`);
  await client.key(cmdKey("KeyC", "c", 67, { commands: ["copy"] }));
  await sleep(500);
  await client.key(cmdKey("KeyV", "v", 86, { commands: ["paste"] }));
  await sleep(1500);
  const c2 = await pageCounts(ctx);
  const pastedRel = c2.relIds.find((id) => !c1.relIds.includes(id));
  const pastedBinds = pastedRel ? await bindingsOf(ctx, pastedRel) : null;
  const errs = await releaseErrors(ctx);
  const origBinds = (await bindingsOf(ctx, st.rel)).length;
  return { selected, before: c0, afterDup: c1, dupBinds, afterPaste: c2, pastedBinds, origBinds, errs: [...new Set(errs.map((e) => e.slice(0, 100)))] };
};

export default [
  {
    name: "P0 fixture: canvas with 3 nodes + supports relation; canvas2 with Evidence only",
    input: "create canvas; drop pr-ev/pr-cl/pr-cl2; relation tool 'supports' drag ev → cl; create canvas2 and drop pr-ev",
    expected: "3 sized nodes; relation 'supports' bound both ends; canvas2 has 1 node",
    run: async (ctx) => {
      const { client } = ctx;
      const n = await ensureNodes(ctx);
      await sleep(800);
      const c = await newCanvas(ctx);
      const st = { canvas: c.path, viewType: c.viewType, paths: n };
      await dropAt(ctx, n.ev, 0.2, 0.45);
      await dropAt(ctx, n.cl, 0.62, 0.3);
      await dropAt(ctx, n.cl2, 0.62, 0.7);
      await client.waitFor(`return window.__dgEditor.getCurrentPageShapes().filter((s) => s.type === "discourse-node").length >= 3`, { label: "3 nodes" });
      await sleep(1500);
      st.ev = await nodeByTitle(ctx, "pr-ev-node");
      st.cl = await nodeByTitle(ctx, "pr-cl-node");
      st.cl2 = await nodeByTitle(ctx, "pr-cl2-node");
      await client.evaluate(`window.__dgEditor.setCurrentTool("discourse-node"); return true;`);
      await client.waitFor(`return !!app.workspace.activeLeaf.view.containerEl.querySelector(".tlui-style-panel__wrapper button")`, { label: "tool panel" });
      await sleep(300);
      await client.evaluate(`[...app.workspace.activeLeaf.view.containerEl.querySelectorAll(".tlui-style-panel__wrapper button")].find((b) => b.textContent.trim() === "supports").click(); return true;`);
      await sleep(300);
      await drag(ctx, await centerOfShape(ctx, st.ev), await centerOfShape(ctx, st.cl));
      await sleep(1500);
      const rels = (await pageCounts(ctx)).relIds;
      st.rel = rels[0];
      await client.evaluate(`window.__dgEditor.setCurrentTool("select"); return true;`);
      const relShape = await shapeById(ctx, st.rel);
      const binds = await bindingsOf(ctx, st.rel);
      const c2 = await newCanvas(ctx);
      st.canvas2 = c2.path;
      await dropAt(ctx, n.ev, 0.3, 0.4);
      await client.waitFor(`return window.__dgEditor.getCurrentPageShapes().filter((s) => s.type === "discourse-node").length >= 1`, { label: "canvas2 node" });
      await sleep(1000);
      st.ev2 = await nodeByTitle(ctx, "pr-ev-node");
      writeP(st);
      return { ids: [st.ev, st.cl, st.cl2], relText: relShape?.props.text, binds: binds.length, relInstance: !!relShape?.meta.relationInstanceId, canvas2Node: !!st.ev2 };
    },
    expect: (a) => ({ pass: a.ids.every(Boolean) && a.relText === "supports" && a.binds === 2 && a.canvas2Node, actual: JSON.stringify(a) }),
  },
  {
    name: "P8 Context tab → Add this relation to canvas",
    input: "canvas2: click pr-ev-node; Context tab lists 'supports → pr-cl-node'; click its '+' (Add this relation to canvas)",
    expected: "new discourse-node shape titled 'pr-cl-node', resized by the load effect (w/h non-zero, not the 200x100 default); relation bound both ends",
    setup: async () => ({}),
    run: async (ctx, state) => {
      const { client, json } = ctx;
      const st = await openPCanvas(ctx, "canvas2");
      const before = (await pageCounts(ctx)).by["discourse-node"] ?? 0;
      const c = await centerOfShape(ctx, st.ev2);
      await clickAt(ctx, c.x, c.y);
      await client.waitFor(`return !!document.querySelector('.dg-node-card-menu button[title="Add this relation to canvas"]') || /No relations found/.test(document.querySelector(".dg-node-card-menu")?.textContent || "")`, { label: "context tab", timeoutMs: 8000 });
      await sleep(400);
      const tabText = await client.evaluate(`return document.querySelector(".dg-node-card-menu").innerText.slice(0, 200);`);
      const btn = await rectOf(ctx, `return [...document.querySelectorAll('.dg-node-card-menu li')].find((li) => li.querySelector("a")?.textContent === "pr-cl-node")?.querySelector('button[title="Add this relation to canvas"]');`);
      if (!btn) return { tabText, btn: null };
      await clickAt(ctx, btn.x, btn.y);
      await client.waitFor(`return window.__dgEditor.getCurrentPageShapes().filter((s) => s.type === "discourse-node").length > ${before}`, { label: "new node", timeoutMs: 6000 });
      const id = await nodeByTitle(ctx, "pr-cl-node");
      state.id = id;
      const first = await shapeById(ctx, id);
      await settle(ctx, id);
      const s = await shapeById(ctx, id);
      const rel = (await pageCounts(ctx)).relIds[0];
      return { tabText, first: { w: first.props.w, h: first.props.h, title: first.props.title }, settled: { w: s.props.w, h: s.props.h, title: s.props.title }, binds: rel ? (await bindingsOf(ctx, rel)).length : 0 };
    },
    expect: (a) => ({
      pass: !!a.settled && a.settled.title === "pr-cl-node" && a.settled.w > 0 && a.settled.h > 0 && !(a.settled.w === 200 && a.settled.h === 100) && a.binds === 2,
      actual: JSON.stringify(a),
    }),
    teardown: async ({ client, json }, state) => {
      if (state.id) await client.evaluate(`window.__dgEditor?.deleteShapes([${json(state.id)}]); return true;`);
      await sleep(800);
    },
  },
  {
    name: "P9 drag wikilink handle onto canvas",
    input: "canvas + split note with [[pr-drag-node]] in Live Preview; dragstart on the link's ⠿ handle; CDP drag-and-drop of its data onto the canvas",
    expected: "handle present; drag data is the obsidian:// URL; a discourse-node shape titled 'pr-drag-node' is created, sized (non-zero, not 200x100)",
    setup: async () => ({}),
    run: async (ctx, state) => {
